#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int A, B;
    if (scanf("%d %d", &A, &B) != 2) return 0;

    int *sequence = malloc((size_t)A * sizeof(int));
    if (sequence == NULL) return 0;

    for (int i = 0; i < A; i++) {
        scanf("%d", &sequence[i]);
    }

    int matched = 0;
    for (int i = 0; i < B; i++) {
        int value;
        scanf("%d", &value);

        while (matched < A && sequence[matched] != value) {
            matched++;
        }
        if (matched < A) {
            matched++;
        }
    }

    puts(matched <= A && matched >= B ? "S" : "N");
    free(sequence);
    return 0;
}
